import base64,hashlib,json,subprocess
from pathlib import Path
FILES={'tools/check_dpu_identity_config.py': {'sha256': '7da80e7bac8794c79b7b60c93a26f6b2ff11b77d7edd8bfcc5aa4135cabea77d', 'base64': ''}, 'board/identity/model_store.py': {'sha256': '5d6cd6fe6ddbff9b236b8d09791d7f013f3d02815c8bde99ae913cc7bc2180f0', 'base64': ''}}
root=Path('/home/root/aura-sface-live-configcheck-20261021')/hashlib.sha256(json.dumps(FILES,sort_keys=True).encode()).hexdigest()[:16]
root.mkdir(parents=True,exist_ok=True)
for name,meta in FILES.items():
 b=base64.b64decode(meta['base64']);assert hashlib.sha256(b).hexdigest()==meta['sha256']
 p=root/name;p.parent.mkdir(parents=True,exist_ok=True)
 if p.exists():assert p.read_bytes()==b
 else:p.write_bytes(b)
fallback=Path('/home/root/aura-handsfree-dialogue-20261020/candidate-0c0a8ab46ec2/camera_live_config/board_identity.json')
original=fallback.read_bytes();config=json.loads(original)
assert config['feature_backend']['kind']=='windows_sface'
model_id='sface-int8-12b2ff5c7de15713'
config['model_id']=model_id;config['database']=str(root/(model_id+'.sqlite3'))
config['threshold']=None;config['ambiguity_margin']=None;config['test_only']=True
modelroot=Path('/home/root/aura-dpu-vision-20261021/staging/03580d3216661ba0/kit')
config['feature_backend']={'kind':'dpu_sface','model':str(modelroot/'sface_public_int8.xmodel'),'manifest':str(modelroot/'sface-manifest.json'),'model_sha256':'12b2ff5c7de157133ebd5aa71665fc5ddcd1f65d9e30e2d6e965e0752e467f25','manifest_sha256':'d52e4343910f7d3c775405c161e3fdf16db27396891dc617b0e5defdb878841b','fallback_config':str(fallback),'max_source_age_ms':min(1000,config['result_ttl_ms'])}
if config.get('enrollment_photos',{}).get('enabled'):config['enrollment_photos']['directory']=str(root/(model_id+'-photos'))
p=root/'TEST_ONLY_NULL_THRESHOLDS.json';data=(json.dumps(config,indent=2)+'\n').encode()
if p.exists():assert p.read_bytes()==data
else:p.write_bytes(data)
assert not Path(config['database']).exists()
result=subprocess.run(['/usr/bin/python3','-B',str(root/'tools/check_dpu_identity_config.py'),'--config',str(p)],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=12)
assert result.returncode==0,result.stderr.decode()[-1500:]
value=json.loads(result.stdout)
assert not value['runner_created'] and not value['field_threshold_validated']
assert not Path(config['database']).exists() and fallback.read_bytes()==original
print(json.dumps({'check':value,'root':str(root),'source_hashes':{k:v['sha256'] for k,v in FILES.items()},'original_config_unchanged':True,'new_database_created':False,'thresholds_null':True,'production_backend_changed':False}))
